// Upgrade default profile names without removing existing records or custom names.
data.names=data.names.map((n,i)=>/^Player [12]$/.test(n)?['Player 1','Player 2'][i]:n);
data.learning=data.learning||{};data.weeks=data.weeks||[1,1];
let section='strength',ballDay='A',partner=false;
const resources={scan:['FA: Take a picture','https://learn.englandfootball.com/sessions/resources/2022/receiving-skills-take-a-picture'],receive:['FIFA: Passing and receiving','https://www.fifatrainingcentre.com/en/practice/elite-sessions/in-possession/john-peacock-passing-and-receiving.php'],pressure:['FA: Receiving under pressure','https://learn.englandfootball.com/sessions/resources/2022/Receiving-the-ball-under-pressure-in-football'],duel:['FIFA: Defending in 1v1','https://www.fifatrainingcentre.com/en/practice/talent-coach-programme/deny-and-protect/defending-in-1v1-orientating-attackers-away-from-goal.php'],width:['FIFA: In-possession video library','https://www.fifatrainingcentre.com/en/resources/game-library/in-possession.php'],transition:['FIFA: Transition-to-attack video library','https://www.fifatrainingcentre.com/en/resources/game-library/transition-to-attacking.php']};
const curriculum=[
{title:'Scan before receiving',ref:'scan',question:'Where is the defender, where is the space, and who can I pass to?',cue:'Check the pressure before the ball arrives.',solo:'Pass against a wall from 4–6 yards. Before the return, glance toward a target gate, then receive toward it. This rehearses the movement; it does not reproduce a real defender.',duo:'One serves while the other checks the space. The server moves left or right after passing; receiver notices the movement and takes the first touch into the other space.',watch:'Watch the scanning demonstration. Pause before the pass arrives. Predict what the receiver needs to see.'},
{title:'First touch with purpose',ref:'receive',question:'Does my first touch set up the next action?',cue:'Touch into the next action.',solo:'Set two gates near the wall. Alternate receiving across your body through each gate, then pass again. Use both feet.',duo:'The server points toward an available gate before passing. Receive through that gate; progress to a defender gently closing one side.',watch:'Follow the receiver’s body position and first touch. Pause and predict the next pass.'},
{title:'Beat a defender',ref:'duel',question:'Which route is the defender protecting?',cue:'Move the defender, then accelerate.',solo:'Approach a cone, use a body feint or inside/outside cut, then accelerate three steps through a gate. Alternate sides. Walk back to recover.',duo:'Play 1v1 to two gates. Defender begins at light pressure. Attacker chooses the open gate. Swap roles after every attempt; no sliding.',watch:'Watch the defending example as an attacker. Identify the route the defender tries to close.'},
{title:'Protect, turn, or pass',ref:'pressure',question:'Can I turn safely, or should I protect and return the pass?',cue:'Keep it when the turn is closed.',solo:'Receive a wall pass, place your body between an imaginary opponent and the ball, then turn away or return the pass. Alternate your chosen action.',duo:'Receive with your brother applying light pressure from behind. Turn only when space opens; otherwise shield and return the ball to a safe target. Match size and pressure; no pushing or holding.',watch:'Compare a safe turn with a protected receive. Explain why forcing a turn can lose possession.'},
{title:'Width and runs behind',ref:'width',question:'Does staying wide help, or is there space to run behind?',cue:'Time the run to the passer.',solo:'Use cones for a wide starting position and a defender. Check toward the ball, then curve your run behind the defender. Walk back; focus on timing and body position.',duo:'Server looks up as the signal to run. Start wide, curve behind a cone defender, then receive a pass into space. Swap roles. Discuss staying onside in a real match.',watch:'In the library, choose creating width/depth or attacking wide areas. Follow a winger before the ball reaches them.'},
{title:'Choose the final action',ref:'width',question:'Should I shoot, cut back, cross, or keep the ball?',cue:'Look up before delivery.',solo:'Dribble past a cone and pass toward a marked cutback target. Alternate with cutting inside toward a shooting gate. Use controlled accuracy, not power.',duo:'One attacks wide while the other moves to a passing target. Look up and deliver to the moving player. Swap roles; add a defender only if a third person joins.',watch:'Choose an attacking-wide-areas or finishing clip. Pause before the final ball and name two options.'},
{title:'React when possession changes',ref:'transition',question:'Should I pressure the ball, support an attack, or recover?',cue:'React, then follow the team plan.',solo:'Dribble between gates. At a chosen signal, turn and recover toward a home cone, then reset. This practices movement; decisions need an opponent.',duo:'Play 1v1 between opposite gates. On a turnover, switch attacking and defending roles immediately. Keep attempts short and rest between them.',watch:'Watch a transition clip. Follow the nearest players for the first few seconds after the ball changes teams.'},
{title:'Connect it in a game',ref:null,question:'What did I see, what did I choose, and what happened?',cue:'Choose one cue that helps you.',solo:'Repeat the two drills you found hardest. Slow them down until the touch or movement is controlled, then add a little pace.',duo:'Play short 1v1 rounds to two gates, swapping roles. Pick one focus such as first touch or shielding. With more players, use 2v2 or 3v3.',watch:'With a parent, choose three successful moments and two learning moments from your own match footage. No upload is needed here.'}
];
function learningRecord(type){const k=player+'|'+(type==='watch'?'week-'+data.weeks[player]:$('date').value+'|'+ballDay)+'|'+type;return data.learning[k]||(data.learning[k]={checks:{},note:''})}
function learnCheck(id,label,r){return '<div class="set"><label><input type="checkbox" data-learn-check="'+id+'" '+(r.checks[id]?'checked':'')+'>'+label+'</label></div>'}
function learnRender(){document.querySelectorAll('[data-section]').forEach(b=>b.classList.toggle('active',b.dataset.section===section));$('strengthArea').hidden=section!=='strength';$('learningArea').hidden=section==='strength';if(section==='strength')return;const week=data.weeks[player],c=curriculum[week-1],r=learningRecord(section);let html='<section class="panel"><div class="row between"><h2>'+escapeHTML(data.names[player])+' • '+(section==='soccer'?'Ball training':'Watch & learn')+'</h2><label>Learning week <select id="learningWeek">'+curriculum.map((c,i)=>'<option value="'+(i+1)+'" '+(i+1===week?'selected':'')+'>'+(i+1)+' · '+c.title+'</option>').join('')+'</select></label></div><p><strong>'+c.title+'</strong></p><p class="note">Match cue: '+c.cue+'</p><p class="muted">Use one idea at a time. Repeat a week when useful; progression is not automatic.</p></section>';
if(section==='soccer'){html+='<div class="row tabs"><button data-ball-day="A" class="'+(ballDay==='A'?'active':'')+'"> Receive & connect</button><button data-ball-day="B" class="'+(ballDay==='B'?'active':'')+'">Wide attacks</button></div><section class="panel"><label><input type="checkbox" id="withBrother" '+(partner?'checked':'')+'> Training with my brother</label><p class="muted">15 minutes total. After lifting, use only the first two blocks during the first two weeks or if tired. Skip extra soccer during tournament weeks. Take breaks whenever needed.</p></section>';
const blocks=[['Comfortable touches',180,'Inside/outside touches and gentle turns. Alternate feet, glance up, and keep the ball close.'],[c.title,420,partner?c.duo:c.solo],[ballDay==='A'?'Pass and find a new angle':'Beat a cone, then deliver',300,ballDay==='A'?(partner?'Pass to your brother, move to a different angle, and receive again. Swap the moving role every minute. Do not stand still after passing.':'Pass to a wall, move a few steps sideways, receive, then repeat. Keep passes controlled and use both feet.'):(partner?'Take turns attacking two gates against light pressure. After escaping, pass to a target. Swap after each attempt and rest.':'Dribble toward a cone. Alternate going outside for a cutback target and inside for a passing/shooting gate. Walk back between attempts.')]];
blocks.forEach((b,i)=>html+='<section class="exercise"><div class="row between"><h3>'+(i+1)+'. '+b[0]+'</h3><span class="pill hold">PRACTICE · '+b[1]/60+' min</span></div><p>'+b[2]+'</p><button class="hold" data-practice="'+b[1]+'" data-practice-label="'+b[0]+'">Start block timer</button>'+learnCheck('block'+i,'Block complete',r)+'</section>');html+='<section class="panel"><h3>One takeaway</h3><p>What improved today? What will you try in the next practice?</p><textarea id="learningNote" rows="3" maxlength="1000" style="width:100%;padding:12px;font:inherit">'+escapeHTML(r.note)+'</textarea><small>Saved on this device when you leave the field.</small></section>';
}else{const resource=c.ref?resources[c.ref]:null;html+='<section class="exercise"><span class="pill hold">10–15 MINUTES</span><h3 style="margin-top:12px">1. Watch with a purpose</h3><p>'+c.watch+'</p>'+(resource?'<a href="'+resource[1]+'" target="_blank" rel="noopener">Open '+resource[0]+' ↗</a><p class="muted">External coaching page with demonstrations or a clip library; some pages may request an account. If playback is unavailable, use the on-page explanation together.</p>':'<p class="muted">Use your family’s match recording in its usual app.</p>')+learnCheck('watched','I watched or reviewed the explanation',r)+'</section><section class="exercise"><h3>2. Pause & predict</h3><p>'+c.question+'</p><p>Pause before the action. Name two options, choose one, and explain why. Then watch what happens.</p>'+learnCheck('discussed','I explained my choice',r)+'</section><section class="exercise"><h3>3. Take it to the field</h3><p>'+c.cue+'</p>'+learnCheck('practised','I tried the idea in training',r)+learnCheck('match','I looked for it in a match',r)+'<p>One example I noticed:</p><textarea id="learningNote" rows="3" maxlength="1000" style="width:100%;padding:12px;font:inherit">'+escapeHTML(r.note)+'</textarea></section><section class="panel"><h3>Position reminders</h3><p><strong>Winger:</strong> create width when useful, recognize runs behind, and look up before delivery.</p><p><strong>Striker:</strong> move off a defender’s shoulder, connect passes, and arrive in scoring spaces.</p><p><strong>Attacking mid:</strong> scan both shoulders, find a passing angle, and support after the pass.</p><small>Follow your coach’s formation and instructions. These concepts can be practiced by both brothers; they are not a confirmed position assignment for Player 2.</small></section>'}const count=Object.values(r.checks).filter(Boolean).length;html+='<p class="muted">'+count+' item'+(count===1?'':'s')+' checked for this '+(section==='watch'?'learning week':'ball session')+'.</p>';$('learningArea').innerHTML=html;}
const strengthRender=render;render=function(){strengthRender();learnRender()};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.section){pause();section=b.dataset.section;render()}if(b.dataset.ballDay){pause();ballDay=b.dataset.ballDay;learnRender()}if(b.dataset.practice){configure(Number(b.dataset.practice),b.dataset.practiceLabel,'hold',true);$('timer').scrollIntoView({behavior:'smooth',block:'nearest'})}});
$('learningArea').addEventListener('change',e=>{if(e.target.id==='learningWeek'){pause();data.weeks[player]=Number(e.target.value);persist();learnRender()}if(e.target.id==='withBrother'){partner=e.target.checked;learnRender()}if(e.target.dataset.learnCheck){learningRecord(section).checks[e.target.dataset.learnCheck]=e.target.checked;persist();learnRender()}});
$('learningArea').addEventListener('input',e=>{if(e.target.id==='learningNote'){learningRecord(section).note=e.target.value;persist()}});
const oldSave=$('saveSettings').onclick;$('saveSettings').onclick=()=>{oldSave();if(data.names[0]==='Player 1')data.names[0]='Player 1';if(data.names[1]==='Player 2')data.names[1]='Player 2';persist();render()};
$('export').onclick=()=>{const out={player:data.names[player],exported:new Date().toISOString(),strength:Object.fromEntries(Object.entries(data.records).filter(([k])=>k.startsWith(player+'|'))),soccerAndLearning:Object.fromEntries(Object.entries(data.learning).filter(([k])=>k.startsWith(player+'|')))};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:'application/json'}));a.download='galaxy-'+data.names[player].replace(/[^a-z0-9]/gi,'-')+'-training-log.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
persist();render();
